function run(response, fila) {
  try {
    if (typeof response === "string") {
      response = JSON.parse(response);
    }

    if (
      !response ||
      !response.resource ||
      !response.resource.items ||
      response.resource.items.length === 0
    ) {
      return null;
    }

    const items = response.resource.items;
    const filaUpper = String(fila || "").toUpperCase();
    let selectedItem = null;

    // tenta encontrar pela fila
    for (let i = 0; i < items.length; i++) {
      const title = String(items[i].title || "").toUpperCase();

      if (
        title === filaUpper ||
        title.indexOf(filaUpper) !== -1 ||
        filaUpper.indexOf(title) !== -1
      ) {
        selectedItem = items[i];
        break;
      }
    }

    // fallback obrigatório: Horário Regular
    if (!selectedItem) {
      for (let j = 0; j < items.length; j++) {
        if (String(items[j].title).toUpperCase() === "HORÁRIO REGULAR") {
          selectedItem = items[j];
          break;
        }
      }
    }

    return selectedItem ? JSON.stringify(selectedItem) : null;

  } catch (e) {
    return null;
  }
}

const DAYS_OF_WEEK = {
  "monday": "Segunda-feira",
  "tuesday": "Terça-feira",
  "wednesday": "Quarta-feira",
  "thursday": "Quinta-feira",
  "friday": "Sexta-feira",
  "saturday": "Sábado",
  "sunday": "Domingo",
};

  function run(response, actualDay) {
    try {
        response = JSON.parse(response);
      const items = response.resource.attendanceHourScheduleItems;
      const itemsFeriados = response.resource.attendanceHourOffItems || [];
      const isFeriado = itemsFeriados.some((item) => item.startDate.includes(actualDay) || item.endDate.includes(actualDay))
      const days = {};

      items.forEach((item) => {
        const key = item.startTime + "-" + item.endTime;
        if(days[key]) days[key].push(item.dayOfWeek);
        else days[key] = [item.dayOfWeek];
      });

      let output = Object.entries(days);

      output = output.map((day) => {
        const [horaInicial, horaFinal] = day[0].split("-");
        const daysOfWeek = day[1].sort((dayA, dayB) => {
            dayA = dayA.toString().toLowerCase().trim();
            dayB = dayB.toString().toLowerCase().trim();
            const sortingArr = Object.keys(DAYS_OF_WEEK);
            return sortingArr.indexOf(dayA) - sortingArr.indexOf(dayB);
        }).map((day) => {
          day = day.toString().toLowerCase().trim();
          return DAYS_OF_WEEK[day] || day
        })
        return `${daysOfWeek.filter((v, index, array) => index === 0 || array.length - 1 === index).join(" a ")} das ${horaInicial.slice(0, 5)}h às ${horaFinal.slice(0, 5)}h`
      }).join('\n e de ');

      if (isFeriado) output += "\n <b>hoje não estamos funcionando por conta do feriado</b>";

      return output;
    } catch(e) {
      return 'segunda a sexta em horário comercial';
    }
  }
